<?php require_once __DIR__.'/api/bootstrap.php';require_login();$m=current_medico();$stats=[];foreach(['pacientes','atendimentos','atestados','laudos'] as $t){$s=db()->prepare("SELECT COUNT(*) n FROM $t WHERE medico_id=?");$s->execute([$m['id']]);$stats[$t]=(int)$s->fetch()['n'];}render_header('Painel');?><h1>Painel médico</h1><p class="muted">Fluxo completo: paciente → atendimento → apoio → revisão médica → documento → assinatura → QR.</p><div class="grid"><?php foreach(['pacientes'=>'Pacientes','atendimentos'=>'Atendimentos','atestados'=>'Atestados emitidos','laudos'=>'Laudos emitidos'] as $k=>$v):?><div class="card"><div class="muted"><?=e($v)?></div><strong style="font-size:30px"><?=number_format($stats[$k],0,',','.')?></strong></div><?php endforeach;?></div><div class="card"><h2>Documentos</h2><a class="btn" href="<?=e(medical_url('atestados/create.php'))?>">Novo atestado</a> <a class="btn" href="<?=e(medical_url('laudos/create.php'))?>">Novo laudo</a> <a class="btn secondary" href="<?=e(medical_url('modelos/'))?>">Gerenciar modelos</a></div><div class="card"><h2>IA de apoio</h2><p>Organiza informações fornecidas pelo médico. Não diagnostica, não escolhe CID, não define incapacidade e não assina documentos.</p><a class="btn" href="<?=e(medical_url('ia/'))?>">Abrir IA de apoio</a></div><?php render_footer();?>